content.css:
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700;800&display=swap');
:root:not(.dark){--background:#faf8f4;--card:#fffefb;--popover:#fffefb;--border:#e6e0d5;--input:#e6e0d5;--muted:#f1ece4;--secondary:#f1ece4;--foreground:#221e19;--color-bg:#faf8f4;--color-bg-subtle:#f1ece4;--color-surface:#fffefb;--color-border:#e6e0d5;--color-border-subtle:#efeae2}
.sth{--sth-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;position:sticky;top:0;z-index:100;border-bottom:1px solid color-mix(in srgb,var(--color-text,#1d1a17) 10%,transparent);font-family:var(--sth-mono)}
/* The translucent blur lives on a pseudo-element: backdrop-filter on .sth itself would make the
   header the containing block for the fixed drawer and scrim, pinning them to the header box. */
.sth::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;background:color-mix(in srgb,var(--color-bg,#fbf9f6) 86%,transparent);-webkit-backdrop-filter:saturate(160%) blur(12px);backdrop-filter:saturate(160%) blur(12px)}
.sth-skip{position:absolute;inset-inline-start:-9999px;top:.5rem;padding:.5rem .9rem;background:var(--color-text,#1d1a17);color:var(--color-bg,#fff);border-radius:.5rem;z-index:1}
.sth-skip:focus{inset-inline-start:.75rem}
.sth-inner{display:flex;align-items:center;gap:2rem;max-width:1180px;margin:0 auto;padding:0 1.5rem;height:64px}
.sth-logo,.sth-panel-logo{display:inline-flex;align-items:center;gap:.6rem;font-family:var(--sth-mono);font-size:.9375rem;font-weight:800;letter-spacing:.09em;color:var(--color-text,#1d1a17);text-decoration:none}
.sth-mark{display:block;width:26px;height:26px}
.sth-nav{display:flex;gap:1.6rem;font-size:.75rem;font-weight:500;letter-spacing:.11em;text-transform:uppercase;margin-inline-start:auto}
.sth-nav a{position:relative;color:var(--color-text-secondary,#525252);text-decoration:none;padding-block:.35rem;transition:color 140ms ease}
.sth-nav a::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--color-brand,#e2603a);transform:scaleX(0);transform-origin:left;transition:transform 160ms ease}
.sth-nav a:hover{color:var(--color-text,#1d1a17)}
.sth-nav a:hover::after{transform:scaleX(1)}
.sth-cta{font-family:var(--sth-mono);font-size:.75rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;line-height:1;white-space:nowrap;padding:.75rem 1.05rem;border-radius:calc(var(--radius,.5rem) * .75);background:var(--color-brand,#e2603a);color:var(--color-on-brand,#fff);text-decoration:none;transition:filter 140ms ease}
.sth-cta:hover{filter:brightness(1.07)}
.sth-cta:focus-visible,.sth-nav a:focus-visible{outline:2px solid var(--color-brand,#e2603a);outline-offset:2px}
.sth-check{display:none}
.sth-burger{display:none;flex-direction:column;justify-content:center;gap:4px;width:38px;height:38px;padding:9px;cursor:pointer}
.sth-burger span{display:block;height:2px;background:var(--color-text,#1d1a17);border-radius:1px}
.sth-scrim{position:fixed;inset:0;background:rgba(0,0,0,.45);opacity:0;pointer-events:none;transition:opacity 140ms ease;z-index:205}
/* Closed drawer is display:none, not parked off-screen — a fixed element sitting outside the
   viewport still adds to the page's scrollable width, which scrolls the whole site sideways.
   Opening animates; closing snaps. */
.sth-panel{display:none;position:fixed;top:0;inset-inline-end:0;height:100dvh;width:min(320px,86vw);background:var(--color-bg,#fbf9f6);border-inline-start:1px solid color-mix(in srgb,var(--color-text,#1d1a17) 12%,transparent);z-index:210;flex-direction:column;gap:1.5rem;padding:1.25rem;overflow-y:auto}
@keyframes sth-slide-in{from{transform:translateX(100%)}to{transform:none}}
.sth-check:checked ~ .sth-scrim{opacity:1;pointer-events:auto}
.sth-check:checked ~ .sth-panel{display:flex;animation:sth-slide-in 220ms ease}
.sth-panel-head{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid color-mix(in srgb,var(--color-text,#1d1a17) 12%,transparent);padding-bottom:.85rem}
.sth-close{font-size:1.75rem;line-height:1;color:var(--color-muted,#8b8b8b);cursor:pointer}
.sth-panel-nav{display:flex;flex-direction:column;gap:1.1rem;font-size:.9375rem;font-weight:500;letter-spacing:.1em;text-transform:uppercase}
.sth-panel-nav a{color:var(--color-text,#1d1a17);text-decoration:none}
.sth-panel-nav a::before{content:"▸ ";color:var(--color-brand,#e2603a)}
.sth-cta--panel{margin-top:auto;text-align:center;padding:.85rem 1.1rem}
@media (max-width:940px){.sth-nav{display:none}.sth-cta:not(.sth-cta--panel){display:none}.sth-burger{display:flex;margin-inline-start:auto}}
@media (prefers-reduced-motion:reduce){.sth-scrim,.sth-nav a::after{transition:none}.sth-check:checked ~ .sth-panel{animation:none}}
